"use client";

import { useState } from "react";
import {
  ChevronDown,
  ChevronRight,
  FileCode2,
  FileJson,
  FilePlus2,
  FileType,
  Folder,
  FolderOpen,
  Trash2,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible";
import { ScrollArea } from "@/components/ui/scroll-area";
import { cn } from "@/lib/utils";
import type { FileTreeNode } from "@/lib/sandbox/types";
import { sandboxPanelClassName } from "@/lib/sandbox/utils";

interface FileTreeProps {
  tree: FileTreeNode[];
  activeFileId?: string;
  onSelectFile: (fileId: string) => void;
  onCreateFile?: () => void;
  onDeleteFile?: (fileId: string) => void;
  className?: string;
}

function FileIcon({ name }: { name: string }) {
  const className = "size-3.5 shrink-0 text-sky-400/80";

  if (name.endsWith(".json")) {
    return <FileJson className={className} />;
  }
  if (name.endsWith(".css")) {
    return <FileType className={className} />;
  }
  return <FileCode2 className={className} />;
}

interface TreeNodeProps {
  node: FileTreeNode;
  depth: number;
  activeFileId?: string;
  onSelectFile: (fileId: string) => void;
  onDeleteFile?: (fileId: string) => void;
}

function TreeNode({
  node,
  depth,
  activeFileId,
  onSelectFile,
  onDeleteFile,
}: TreeNodeProps) {
  const [open, setOpen] = useState(true);

  if (node.type === "folder") {
    return (
      <Collapsible open={open} onOpenChange={setOpen}>
        <CollapsibleTrigger
          className="flex w-full items-center gap-1.5 rounded-md px-2 py-1.5 text-xs text-muted-foreground hover:bg-muted/40 hover:text-foreground"
          style={{ paddingLeft: `${depth * 12 + 8}px` }}
        >
          {open ? (
            <ChevronDown className="size-3.5 shrink-0" />
          ) : (
            <ChevronRight className="size-3.5 shrink-0" />
          )}
          {open ? (
            <FolderOpen className="size-3.5 shrink-0 text-amber-400/80" />
          ) : (
            <Folder className="size-3.5 shrink-0 text-amber-400/80" />
          )}
          <span className="truncate">{node.name}</span>
        </CollapsibleTrigger>
        <CollapsibleContent>
          {node.children?.map((child) => (
            <TreeNode
              key={child.id}
              node={child}
              depth={depth + 1}
              activeFileId={activeFileId}
              onSelectFile={onSelectFile}
              onDeleteFile={onDeleteFile}
            />
          ))}
        </CollapsibleContent>
      </Collapsible>
    );
  }

  const isActive = node.fileId === activeFileId;

  return (
    <div
      className="group flex items-center"
      style={{ paddingLeft: `${depth * 12 + 8}px` }}
    >
      <button
        type="button"
        onClick={() => node.fileId && onSelectFile(node.fileId)}
        className={cn(
          "flex min-w-0 flex-1 items-center gap-1.5 rounded-md px-2 py-1.5 text-xs transition-colors",
          isActive
            ? "bg-muted text-foreground"
            : "text-muted-foreground hover:bg-muted/40 hover:text-foreground"
        )}
      >
        <FileIcon name={node.name} />
        <span className="truncate">{node.name}</span>
      </button>
      {onDeleteFile && node.fileId ? (
        <Button
          variant="ghost"
          size="icon-xs"
          className="mr-1 opacity-0 transition-opacity group-hover:opacity-100"
          onClick={() => onDeleteFile(node.fileId!)}
          aria-label={`Delete ${node.name}`}
        >
          <Trash2 className="size-3 text-muted-foreground" />
        </Button>
      ) : null}
    </div>
  );
}

export function FileTree({
  tree,
  activeFileId,
  onSelectFile,
  onCreateFile,
  onDeleteFile,
  className,
}: FileTreeProps) {
  return (
    <div className={sandboxPanelClassName(className)}>
      <div className="flex items-center justify-between border-b border-white/[0.06] bg-[#101012] px-3 py-2">
        <span className="text-[11px] font-medium uppercase tracking-[0.12em] text-zinc-500">
          Explorer
        </span>
        {onCreateFile ? (
          <Button variant="ghost" size="icon-xs" onClick={onCreateFile}>
            <FilePlus2 />
          </Button>
        ) : null}
      </div>
      <ScrollArea className="h-full max-h-[520px]">
        <div className="p-2">
          {tree.map((node) => (
            <TreeNode
              key={node.id}
              node={node}
              depth={0}
              activeFileId={activeFileId}
              onSelectFile={onSelectFile}
              onDeleteFile={onDeleteFile}
            />
          ))}
        </div>
      </ScrollArea>
    </div>
  );
}

export type ViewportSize = "desktop" | "tablet" | "mobile";
export type ConsoleLevel = "log" | "info" | "warn" | "error";
export type PreviewStatus = "idle" | "loading" | "ready" | "error";

export interface SandboxFile {
  id: string;
  name: string;
  path: string;
  language: "tsx" | "ts" | "css" | "json";
  content: string;
  isDirty?: boolean;
}

export interface ConsoleMessage {
  id: string;
  level: ConsoleLevel;
  message: string;
  timestamp: Date;
  source?: string;
}

export interface PackageInstallEvent {
  id: string;
  name: string;
  version: string;
  status: "pending" | "success" | "error";
  output?: string;
}

export interface RuntimeError {
  title: string;
  message: string;
  stack: string;
  file: string;
  line: number;
  column?: number;
}

export interface FileTreeNode {
  id: string;
  name: string;
  type: "file" | "folder";
  children?: FileTreeNode[];
  fileId?: string;
}

export interface SandboxState {
  files: SandboxFile[];
  originalContents: Record<string, string>;
  activeFileId: string;
  fileTree: FileTreeNode[];
  consoleMessages: ConsoleMessage[];
  installEvents: PackageInstallEvent[];
  runtimeError: RuntimeError | null;
  previewStatus: PreviewStatus;
  viewport: ViewportSize;
  previewSrcDoc: string;
  consoleCollapsed: boolean;
}

import type { FileTreeNode, SandboxFile } from "./types";

export function getLanguageLabel(language: SandboxFile["language"]): string {
  const labels: Record<SandboxFile["language"], string> = {
    tsx: "TypeScript React",
    ts: "TypeScript",
    css: "CSS",
    json: "JSON",
  };
  return labels[language];
}

export function getLanguageBadge(language: SandboxFile["language"]): string {
  const badges: Record<SandboxFile["language"], string> = {
    tsx: "TSX",
    ts: "TS",
    css: "CSS",
    json: "JSON",
  };
  return badges[language];
}

export function formatTimestamp(date: Date): string {
  return date.toLocaleTimeString("en-US", {
    hour12: false,
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  });
}

export function formatCode(content: string): string {
  const lines = content.split("\n");
  let indent = 0;
  const formatted: string[] = [];

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed) {
      formatted.push("");
      continue;
    }

    if (/^[\}\]\)]/.test(trimmed)) {
      indent = Math.max(0, indent - 1);
    }

    formatted.push(`${"  ".repeat(indent)}${trimmed}`);

    const openBrackets = (trimmed.match(/[\{\[\(]/g) || []).length;
    const closeBrackets = (trimmed.match(/[\}\]\)]/g) || []).length;
    indent += openBrackets - closeBrackets;
    indent = Math.max(0, indent);
  }

  return formatted.join("\n");
}

export function findFileIdInTree(
  nodes: FileTreeNode[],
  fileId: string
): string | null {
  for (const node of nodes) {
    if (node.type === "file" && node.fileId === fileId) {
      return node.id;
    }
    if (node.children) {
      const found = findFileIdInTree(node.children, fileId);
      if (found) return found;
    }
  }
  return null;
}

export function removeFileFromTree(
  nodes: FileTreeNode[],
  fileId: string
): FileTreeNode[] {
  return nodes
    .filter((node) => !(node.type === "file" && node.fileId === fileId))
    .map((node) =>
      node.children
        ? { ...node, children: removeFileFromTree(node.children, fileId) }
        : node
    );
}

export function addFileToTree(
  nodes: FileTreeNode[],
  file: SandboxFile
): FileTreeNode[] {
  const parts = file.path.split("/");
  if (parts.length === 1) {
    return [
      ...nodes,
      {
        id: `tree-${file.id}`,
        name: file.name,
        type: "file" as const,
        fileId: file.id,
      },
    ];
  }

  const [folderName, ...rest] = parts;
  const folderId = `folder-${folderName}`;
  const existingFolderIndex = nodes.findIndex(
    (node) => node.type === "folder" && node.name === folderName
  );

  if (existingFolderIndex >= 0) {
    const folder = nodes[existingFolderIndex];
    const updatedFolder: FileTreeNode = {
      ...folder,
      children: addFileToTree(folder.children ?? [], {
        ...file,
        path: rest.join("/"),
      }),
    };
    return nodes.map((node, index) =>
      index === existingFolderIndex ? updatedFolder : node
    );
  }

  return [
    ...nodes,
    {
      id: folderId,
      name: folderName,
      type: "folder" as const,
      children: addFileToTree([], { ...file, path: rest.join("/") }),
    },
  ];
}

export function sandboxPanelClassName(className?: string): string {
  return [
    "overflow-hidden rounded-xl border border-white/[0.06] bg-[#101012]/90",
    className,
  ]
    .filter(Boolean)
    .join(" ");
}

export function getViewportWidth(viewport: "desktop" | "tablet" | "mobile") {
  const widths = {
    desktop: "100%",
    tablet: "768px",
    mobile: "390px",
  } as const;
  return widths[viewport];
}

export function formatRuntimeErrorForCopy(error: {
  title: string;
  message: string;
  stack: string;
  file: string;
  line: number;
  column?: number;
}): string {
  return `${error.title}: ${error.message}
at ${error.file}:${error.line}${error.column ? `:${error.column}` : ""}

${error.stack}`;
}
